export type RuleMatcher = 
/**  `example.com` and every subdomain. */
{ kind: "domain_suffix"; value: string } | 
/**  Any domain containing the text. */
{ kind: "domain_keyword"; value: string } | 
/**  Exactly this domain. */
{ kind: "domain_full"; value: string } | 
/**  An IP range, e.g. `192.168.0.0/16` or `10.0.0.1`. */
{ kind: "ip_cidr"; value: string } | 
/**  A geo database code, e.g. `cn`, `private`. */
{ kind: "geo_ip"; value: string } | 
/**  Destination port. */
{ kind: "port"; value: number } | 
/**  Executable name on this machine, e.g. `chrome.exe`. */
{ kind: "process_name"; value: string } | 
/**
 *  Every pattern in a rule set. `value` is the set id, not the set name:
 *  renaming a set must not break the rules that point at it.
 */
{ kind: "rule_set"; value: string };

export type RuleSet = RuleSet_Serialize | RuleSet_Deserialize;

/**  How the set is kept up to date. */
export type RuleSetSource = 
/**  Fetched from a URL on a timer. */
"remote" | 
/**  Pasted by the user; never refreshed. */
"local";

export type RuleSet_Deserialize = {
	id: string,
	name: string,
	enabled: boolean,
	source: RuleSetSource,
	/**  Empty for `Local` sets. */
	url: string,
	/**  `0` means "only when I press refresh". */
	update_interval_minutes: number | null,
	updated_at_ms?: number | null,
	/**
	 *  How many entries the last parse produced. Kept so the UI can show
	 *  something before the file is read.
	 */
	entry_count: number | null,
	last_error?: string | null,
};

export type RuleSet_Serialize = {
	id: string,
	name: string,
	enabled: boolean,
	source: RuleSetSource,
	/**  Empty for `Local` sets. */
	url: string,
	/**  `0` means "only when I press refresh". */
	update_interval_minutes: number | null,
	updated_at_ms: number | null,
	/**
	 *  How many entries the last parse produced. Kept so the UI can show
	 *  something before the file is read.
	 */
	entry_count: number | null,
	last_error: string | null,
};

/**  What the rule table would do with one hostname. */
export type RuleTest = RuleTest_Serialize | RuleTest_Deserialize;

/**  What the rule table would do with one hostname. */
export type RuleTest_Deserialize = {
	/**  Name of the rule that caught it, or `None` when nothing did. */
	rule?: string | null,
	/**  The action that rule takes; `None` means "fell through to the default". */
	action?: RuleAction | null,
	/**
	 *  Rules that could not be judged from a hostname alone (geoip / port /
	 *  process) and were skipped. Reporting them is the difference between
	 *  "your rules do not cover this" and "I could not tell".
	 */
	skipped: number | null,
};

/**  What the rule table would do with one hostname. */
export type RuleTest_Serialize = {
	/**  Name of the rule that caught it, or `None` when nothing did. */
	rule: string | null,
	/**  The action that rule takes; `None` means "fell through to the default". */
	action: RuleAction | null,
	/**
	 *  Rules that could not be judged from a hostname alone (geoip / port /
	 *  process) and were skipped. Reporting them is the difference between
	 *  "your rules do not cover this" and "I could not tell".
	 */
	skipped: number | null,
};

export type Security = Security_Serialize | Security_Deserialize;

export type Security_Deserialize = { kind: "None" } | { kind: "Tls"; sni?: string | null; alpn?: string[]; 
/**
 *  Skip certificate verification. Self-signed certificates and
 *  bare-IP servers are common, and every other client ships this
 *  switch (`allowInsecure`, Clash's `skip-cert-verify`); without it
 *  those nodes simply cannot be used.
 * 
 *  sing-box honours this (`tls.insecure`). Xray removed
 *  `allowInsecure` in 26.x — it refuses to start when it sees the key —
 *  so for Xray the only honest way to accept a self-signed server is
 *  `pinned_cert_sha256`.
 */
allow_insecure?: boolean; 
/**
 *  SHA-256 of the server certificate (hex, colons optional). This is
 *  Xray's `pinnedPeerCertSha256`: instead of trusting any certificate
 *  it trusts exactly this one, which is stricter than skipping
 *  verification.
 */
pinned_cert_sha256?: string[] } | { kind: "Reality"; public_key: string; short_id: string; server_name: string; 
/**
 *  uTLS ClientHello fingerprint (`fp` in share links). Xray needs one
 *  and every client defaults to chrome, so old data can omit it.
 */
fingerprint?: string; 
/**  Reality spider path (`spx`). Only Xray consumes it. */
spider_x?: string };

export type Security_Serialize = { kind: "None" } | { kind: "Tls"; sni: string | null; alpn: string[]; 
/**
 *  Skip certificate verification. Self-signed certificates and
 *  bare-IP servers are common, and every other client ships this
 *  switch (`allowInsecure`, Clash's `skip-cert-verify`); without it
 *  those nodes simply cannot be used.
 * 
 *  sing-box honours this (`tls.insecure`). Xray removed
 *  `allowInsecure` in 26.x — it refuses to start when it sees the key —
 *  so for Xray the only honest way to accept a self-signed server is
 *  `pinned_cert_sha256`.
 */
allow_insecure: boolean; 
/**
 *  SHA-256 of the server certificate (hex, colons optional). This is
 *  Xray's `pinnedPeerCertSha256`: instead of trusting any certificate
 *  it trusts exactly this one, which is stricter than skipping
 *  verification.
 */
pinned_cert_sha256: string[] } | { kind: "Reality"; public_key: string; short_id: string; server_name: string; 
/**
 *  uTLS ClientHello fingerprint (`fp` in share links). Xray needs one
 *  and every client defaults to chrome, so old data can omit it.
 */
fingerprint: string; 
/**  Reality spider path (`spx`). Only Xray consumes it. */
spider_x: string };

/**
 *  Backend-owned settings: everything here must survive an app restart.
 *  Pure UI preferences (theme, sidebar state, table density) live in the
 *  frontend only — see ARCHITECTURE.md §3.
 */
export type Settings = Settings_Serialize | Settings_Deserialize;

/**
 *  Backend-owned settings: everything here must survive an app restart.
 *  Pure UI preferences (theme, sidebar state, table density) live in the
 *  frontend only — see ARCHITECTURE.md §3.
 */
export type Settings_Deserialize = {
	/**  Local mixed inbound (HTTP + SOCKS) port. */
	mixed_port?: number,
	/**  Control/API port used by the engine for stats & connections. */
	api_port?: number,
	allow_lan?: boolean,
	mode?: ProxyMode,
	/**  Whether X-Matrix currently owns the Windows system proxy. */
	system_proxy?: boolean,
	auto_start?: boolean,
	language?: Language,
	/**
	 *  Start the last used node as soon as the app comes up. Off by default:
	 *  an app that quietly opens a tunnel on launch is a surprise, and this
	 *  machine may already have another client doing that.
	 */
	auto_connect?: boolean,
	/**
	 *  The node and kernel that were running when the app last closed. Kept so
	 *  "connect on launch" knows what to start, and so the UI can preselect it.
	 */
	last_node_id?: string | null,
	/**
	 *  Persisted as the kernel's own spelling (`xray` / `sing-box`) because the
	 *  domain must not depend on the engine module.
	 */
	last_engine?: string | null,
	/**
	 *  How chatty the kernel log should be. `Warn` keeps the file readable;
	 *  `Debug` is what you switch to when a node will not connect.
	 */
	log_level?: LogLevel,
	/**
	 *  Re-test every node this often, in minutes. `0` means "only when I press
	 *  the button": an app that starts hammering node endpoints on its own is
	 *  something people notice on a metered connection.
	 */
	auto_test_minutes?: number,
	/**
	 *  Bypass list written into the Windows proxy settings while X-Matrix owns
	 *  them. Loopback and RFC1918 are in the default; users behind a corporate
	 *  PAC or a local gateway usually need to add one more entry.
	 */
	proxy_bypass?: string,
	/**
	 *  What "real latency" and a url-test group probe. gstatic's 204 endpoint is
	 *  the de-facto standard, but it is blocked on some networks, so the URL has
	 *  to be editable or the feature is useless exactly where it is needed.
	 */
	test_url?: string,
	/**
	 *  `User-Agent` sent when fetching subscriptions. Empty means "our own".
	 *  Plenty of providers only serve a Clash UA and answer anything else with
	 *  an empty body or a 403, so this is the one header worth exposing.
	 */
	subscription_user_agent?: string,
	/**
	 *  Comma separated resolver IPs. Empty means "let the kernel use the system
	 *  resolver". Only literals are accepted: a hostname here would need the
	 *  system resolver to resolve the resolver, which is how DNS loops start.
	 */
	dns_servers?: string,
	/**
	 *  Come up with the window hidden, tray only. For people who launch this at
	 *  login and never want to see it.
	 */
	start_minimized?: boolean,
	/**
	 *  What the window's X button does. `true` (the default) hides to tray and
	 *  keeps the tunnel up; `false` quits and restores the system proxy, which
	 *  is what someone who thinks of X as "close the program" expects.
	 */
	close_to_tray?: boolean,
};

