export type Subscription = Subscription_Serialize | Subscription_Deserialize;

export type Subscription_Deserialize = {
	id: string,
	name: string,
	url: string,
	enabled: boolean,
	/**  Minutes between automatic refreshes. `0` means "only when I ask". */
	update_interval_minutes: number | null,
	/**  Unix milliseconds of the last successful fetch. */
	updated_at_ms?: number | null,
	node_count: number | null,
	/**
	 *  Why the last fetch failed, kept so the UI can explain a stale list
	 *  instead of silently showing yesterday's nodes.
	 */
	last_error?: string | null,
	/**  Bytes used so far, from the provider's `subscription-userinfo` header. */
	traffic_used?: number | null,
	/**  Bytes in the plan, same header. */
	traffic_total?: number | null,
	/**  Unix milliseconds when the plan expires, same header. */
	expires_at_ms?: number | null,
};

export type Subscription_Serialize = {
	id: string,
	name: string,
	url: string,
	enabled: boolean,
	/**  Minutes between automatic refreshes. `0` means "only when I ask". */
	update_interval_minutes: number | null,
	/**  Unix milliseconds of the last successful fetch. */
	updated_at_ms: number | null,
	node_count: number | null,
	/**
	 *  Why the last fetch failed, kept so the UI can explain a stale list
	 *  instead of silently showing yesterday's nodes.
	 */
	last_error: string | null,
	/**  Bytes used so far, from the provider's `subscription-userinfo` header. */
	traffic_used: number | null,
	/**  Bytes in the plan, same header. */
	traffic_total: number | null,
	/**  Unix milliseconds when the plan expires, same header. */
	expires_at_ms: number | null,
};

/**  What the UI shows on the settings page. */
export type SystemProxyStatus = {
	/**  True when *we* are the ones holding the system proxy. */
	active: boolean,
	/**  True when the system currently routes through some proxy (ours or not). */
	enabled: boolean,
	/**  Whatever `ProxyServer` currently says. */
	server: string,
	/**  A leftover snapshot means the previous run died while holding it. */
	snapshot_present: boolean,
};

/**  Cumulative traffic counters, plus (when available) the live connection list. */
export type TrafficSample = {
	/**  Bytes sent through the proxy outbound. */
	up_total: number | null,
	/**  Bytes received through the proxy outbound. */
	down_total: number | null,
	/**  Bytes that bypassed the proxy (Xray only; 0 on sing-box). */
	direct_up: number | null,
	direct_down: number | null,
	/**  Empty on Xray: that kernel has no connection-list API. */
	connections: ConnectionInfo[],
	/**
	 *  True when the kernel can report connections at all, so the UI can show
	 *  "this kernel has no connection list" instead of "no connections".
	 */
	supports_connections: boolean,
};

export type Transport = Transport_Serialize | Transport_Deserialize;

export type Transport_Deserialize = { kind: "Tcp" } | { kind: "Ws"; path?: string; host?: string | null } | { kind: "Grpc"; service_name: string };

export type Transport_Serialize = { kind: "Tcp" } | { kind: "Ws"; path: string; host: string | null } | { kind: "Grpc"; service_name: string };

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

